PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,full_name TEXT NOT NULL,email TEXT UNIQUE,phone TEXT UNIQUE,password_hash TEXT,role TEXT NOT NULL CHECK(role IN('citizen','agent','moderator','admin')),organization TEXT,region TEXT,is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(email IS NOT NULL OR phone IS NOT NULL));
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,citizen_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,category TEXT NOT NULL CHECK(category IN('danger','accident','medical','fire','infrastructure')),urgency TEXT NOT NULL CHECK(urgency IN('low','medium','high','critical')),description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=1000),latitude REAL,longitude REAL,address_approx TEXT,status TEXT NOT NULL DEFAULT 'received' CHECK(status IN('received','in_progress','resolved')),moderation_status TEXT NOT NULL DEFAULT 'pending' CHECK(moderation_status IN('pending','approved','rejected')),tracking_code_hash TEXT NOT NULL UNIQUE,media_key TEXT,media_type TEXT,assigned_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,resolved_at TEXT,CHECK((latitude IS NULL AND longitude IS NULL) OR (latitude BETWEEN -90 AND 90 AND longitude BETWEEN -180 AND 180)));
CREATE TABLE IF NOT EXISTS report_updates(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,old_status TEXT,new_status TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(rate_key TEXT NOT NULL,window_start INTEGER NOT NULL,hits INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(rate_key,window_start));
CREATE INDEX IF NOT EXISTS idx_reports_public ON reports(moderation_status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reports_status ON reports(status,urgency,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reports_assigned ON reports(assigned_user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_updates_report ON report_updates(report_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_rate_window ON rate_limits(window_start);